return {["Sheet1"]={["1"]={["descri"]=[[这里是刑部大堂，厅堂高挂“明镜高悬”横匾，正堂位坐主审官，一派威武的样子，两边是森严、寂静、兵卒列队，手持棍棒，面目严肃，但凡罪大恶极之人皆在此听候发落。]],["family"]=[[guanfu]],["showNpc"]=[[lingyun;yantianyun;luqianhou;xulaotou;jiangyi]],["text"]=[[官府]],["titleImg"]=[[titleImg1.png]]},["10"]={["descri"]=[[这里是个宽广的大厅，高大的盘龙柱一人都合抱不过来。这里是平日谷主召集教众们议事的地方，大厅正中供奉着五圣--毒蛇，蜘蛛，蜈蚣，蝎子，蟾蜍的画像。]],["family"]=[[wudu]],["showNpc"]=[[yanshilou;shaqianli1;dinghongdie;hepopo;luoqiansang]],["text"]=[[万灵谷]],["titleImg"]=[[titleImg1.png]]},["11"]={["descri"]=[[这里就是江湖上闻风丧胆的“伏龙山”。自从“伏龙歼衡山”一役将衡山宗打得一蹶不振之后，帮主伏龙水上漂的名头威震江湖。]],["family"]=[[tiezhang]],["showNpc"]=[[heying;renxian;rentiannan;wangdangzhi;qinhongyan]],["text"]=[[伏龙山]],["titleImg"]=[[titleImg1.png]]},["12"]={["descri"]=[[这就是拜日教教主平日发号施令的地方，殿中无窗，殿口点着明晃晃的蜡烛，大殿彼端高设一座。]],["family"]=[[riyueshenjiao]],["showNpc"]=[[baodachu;yanglianting;dongfangbubai;gudanian;moli]],["text"]=[[拜日教]],["titleImg"]=[[titleImg1.png]]},["13"]={["descri"]=[[这里是雪山寺的内殿，也是掌门人见客的地方。雪山寺的如今的主持乃是葛伦布，乃是西域不世出的武林宗师。传说雪山寺真正的高手并非是他，另有人在。]],["family"]=[[mizong]],["showNpc"]=[[yabutuoluo;gelunbu;huangjiaofawang;shamoke;yamuduo;xumi]],["text"]=[[雪山寺]],["titleImg"]=[[titleImg1.png]]},["14"]={["descri"]=[[这里是天狼教总舵所在地天狼洞。洞内灯火通明，正中一把虎皮椅上端坐着天狼教掌门人魏师道。洞壁上装饰着虎皮、鹿头、雕羽，及一些字画。]],["family"]=[[xingxiu]],["showNpc"]=[[baiduzi;xinghui;weishidao;laolitou;gaochang]],["text"]=[[天狼教]],["titleImg"]=[[titleImg1.png]]},["15"]={["descri"]=[[这是『鸩羽山庄』的大厅，内部摆设极尽豪华，当中一张黑色檀木条案，上面陈放着精美的花瓶和一些珍贵的瓷器，四壁挂满名家的字画。]],["family"]=[[baituoshan]],["showNpc"]=[[shenjiaolian;ouyangxiao;ouyangbo;ouyangnian;qinji]],["text"]=[[鸩羽山]],["titleImg"]=[[titleImg1.png]]},["16"]={["descri"]=[[龙城旧都是燕氏一脉世居之地，燕氏乃昔日大燕国的后裔，后来日见式微，但其弟子却一心一意想光复大燕。其武功见长于以彼之道，还施彼身，端的十分厉害。]],["family"]=[[murong]],["showNpc"]=[[xiexiaoya;liurenxing;murongxing;liqingyao;murongjie]],["text"]=[[燕氏皇族]],["titleImg"]=[[titleImg1.png]]},["17"]={["descri"]=[[明教大殿十分空旷，殿顶高悬八盏金灯，两旁是精壮佩剑武士剑气森严逼人。正中设一宝座，前有一雕花檀木案，案头供明教圣火令六枚。宝座后立有一扇玉屏，屏中画正是明教圣火图，烈焰直逼日月。]],["family"]=[[mingjiao]],["showNpc"]=[[chenzhi;heweiping;yinyiqi;fanshaoqi;luchangfeng;suboran;yangxu;sufu]],["text"]=[[明教]],["titleImg"]=[[titleImg1.png]]},["18"]={["descri"]=[[这里是唐门的议事大厅。发生重大事情的时候，唐门的长辈在此聚集商量。整个大厅的建筑很奇怪，地面黝黑发亮，是唐门平时冶炼暗器所剩铁屑所熔制成的整块。]],["family"]=[[tangmen]],["showNpc"]=[[tanglei;tangtian;tangbuping1;tangsi;tangshiba]],["text"]=[[唐门]],["titleImg"]=[[titleImg1.png]]},["19"]={["descri"]=[[这里是蓬莱山庄的正厅。整个大厅十分宽阔。厅中挂满了各种名家的书法真迹。但最显眼的则是正中挂的一幅对联：到岸请君回首望，蓬莱宫在海中央。]],["family"]=[[taohuadao]],["showNpc"]=[[mengqingshi;yapu1;yujianzhou;longzi;quandayou]],["text"]=[[蓬莱岛]],["titleImg"]=[[titleImg1.png]]},["2"]={["descri"]=[[这是一座古朴的殿堂。西首的墙上挂满了各类武功图谱，不少白须白眉的老僧正端坐在图谱画轴之前，似乎在苦苦思索。]],["family"]=[[shaolin]],["showNpc"]=[[miaozhen;juenan;yuannandashi;yuantongdashi;saodiseng;miaoyan]],["text"]=[[少林派]],["titleImg"]=[[titleImg1.png]]},["20"]={["descri"]=[[这里是问情宫的前厅，光线很差，全靠大厅正中间的梁上悬挂着一颗夜明珠，映射出淡淡的黄光。厅柱是由石头砌成的，上面似乎还写着一些什么字--你怎么也看不清楚了。]],["family"]=[[gumu]],["showNpc"]=[[yansiqi;huowuying;yangwulv;laopu;yanfeng]],["text"]=[[问情宫]],["titleImg"]=[[titleImg1.png]]},["21"]={["descri"]=[[玉皇阁高十三米坐北朝南，采用仿木结构均用砖砌成。外观下阁上亭。下圆下方，造型奇特，是一座集蒙古包与阁楼巧妙结合，具有元代风格的建筑。阁内供有真武铜像一尊。]],["family"]=[[kongtong]],["showNpc"]=[[monianqing;muxiong;moxueyi;xielaotou;duyan]],["text"]=[[崆峒派]],["titleImg"]=[[titleImg1.png]]},["22"]={["descri"]=[[这是海鲸帮醒龙堂，正首坐着一位大汉，左右摆放的八张太师椅，上面坐着海鲸帮的八位堂主，周遭还有各堂随从肃立其后。]],["family"]=[[haijing]],["showNpc"]=[[fengyan;xingtianya;qiumuzhong;guyanfeng;shilong]],["text"]=[[海鲸帮]],["titleImg"]=[[titleImg1.png]]},["23"]={["descri"]=[[这里是幽冥教的无魂殿，这里光线很暗，只能隐约看见自己周围，大殿的中央有一个巨大的黑影，似乎是一张巨型的座椅，上面还坐着一个人。]],["family"]=[[youming]],["showNpc"]=[[duwuchang;duomingpanduan;yewangsheng;youmingjiaozhu;youmingfuren;qinming]],["text"]=[[幽冥教]],["titleImg"]=[[titleImg1.png]]},["24"]={["descri"]=[[这里是树林中的一片比较大的空地，名曰：青草坪。因为处于密林之中所以这里平时很少有人来，但是不知道为什么，这里却经常有人迹出现。你看，又一个来了。]],["family"]=[[tianshan]],["showNpc"]=[[dingxiang;qinduanxuan;gaoge;tianshuzi1;xuzhuzi;baifalaozhe;xiaoyan]],["text"]=[[虚渺宫]],["titleImg"]=[[titleImg1.png]]},["25"]={["descri"]=[[独酌楼立于落月山庄南边，最是靠近西湖，楼内装饰清雅，别具一格，却见一人气质儒雅立于窗边赏月饮酒，身后一男一女皆抱剑而立，你感受着周遭的静逸，心中生出莫名感觉。]],["family"]=[[luoyue]],["showNpc"]=[[luohuanjun;xiaoziyuan;xiaoyilong;zhaomisheng;liboyong]],["text"]=[[落月山庄]],["titleImg"]=[[titleImg1.png]]},["26"]={["descri"]=[[富贵楼整五层建筑，楼内装饰极其奢侈华贵，地面由大理石嵌金为地板，铺设西域购入金丝绒地毯。楼中每层都摆放着价值连城的宝物，越往上越珍贵，而帮主便在第五层处理事务。]],["family"]=[[jinqianbang]],["showNpc"]=[[shenyuanlong;zhuhua;shangguanyu;shangguanyao;liusihai;heishishangren]],["text"]=[[财神帮]],["titleImg"]=[[titleImg1.png]]},["27"]={["descri"]=[[永夜楼大厅内光线昏暗，只燃着数盏烛灯，四角置香炉，窗前竹影清冽冷涩。正中天窗以粗红绳悬挂无数名刀利刃，乃是代代永夜楼最杰出的已故杀手之物。数十级台阶之上，一把黑檀雕龙宝座是永夜楼主的象征。]],["family"]=[[yongyelou]],["showNpc"]=[[lan;xia;yongye;jiang;xiu]],["text"]=[[永夜楼]],["titleImg"]=[[titleImg1.png]]},["28"]={["descri"]=[[天竞门内楼台水榭，乐音缭绕，隐约夹杂外面的喧嚣声，各庭院甬道相连，回廊转折，四处圆窗均只开月牙形的半扇，取阴阳八卦之意，周围多设色彩艳丽的脸谱做装饰，也不缺四君子的绘画和刺绣，风格驳杂不一。]],["family"]=[[tianjingmen]],["showNpc"]=[[yangqiubai;gongsunqi;jiguangling;kongdaoren;baishiding;yaobuyi]],["text"]=[[天竞门]],["titleImg"]=[[titleImg1.png]]},["3"]={["descri"]=[[这里是供奉元始天尊的大殿。殿内香烟缭绕，正中央塑着元始天尊的金身，旁边还塑着几位道友如太乙、俱留孙、云中子、广和子等等的像，正聚在一处或躺或坐，或棋或茶。]],["family"]=[[quanzhen]],["showNpc"]=[[yinzhiping;qiuchuji;mayu;wangchongyang;lidaoshi;zhongque]],["text"]=[[全真教]],["titleImg"]=[[titleImg1.png]]},["4"]={["descri"]=[[这是高僧们的静修之处。整堂全以松木制成，板门木柱，木料均不去皮，天然质朴，和一路行来金碧辉煌的殿堂截然不同。东首一个和尚面朝里壁一动不动。]],["family"]=[[dali]],["showNpc"]=[[zhenhe;xinfangdashi;xinxuanchanshi;zhensui;yuzhen]],["text"]=[[天龙寺]],["titleImg"]=[[titleImg1.png]]},["5"]={["descri"]=[[这里是丐帮帮众聚会场所，地上横七竖八排着不少草蒲团。虽然看起来似乎很凌乱，其实却甚是合乎帮规：何人做何职司，前后顺序，一目了然。]],["family"]=[[gaibang]],["showNpc"]=[[shihaifeng;wukun;jiangshangyou1;shenguang;mingchangge]],["text"]=[[丐帮]],["titleImg"]=[[titleImg1.png]]},["6"]={["descri"]=[[这就是峨眉山的主峰金顶了。此峰耸立大地，高入云表，秀丽壮美，登上金顶，视野豁然开朗，鸟瞰脚下，但见群峰涌绿叠翠，三江如丝如带；回首远眺，则见大雪山横亘天际，贡嘎山直插苍穹。]],["family"]=[[emei]],["showNpc"]=[[baijianfeng;xuanlingshitai;baoxiangshenni;baoguangshitai;huayan]],["text"]=[[峨眉派]],["titleImg"]=[[titleImg1.png]]},["7"]={["descri"]=[[你到了武当山最为宏大的紫霄宫。殿宇依山而筑，高低错落有致。周围古木森林，翠竹成林，景色清幽。这里是武当师徒的主要活动场所。]],["family"]=[[wudang]],["showNpc"]=[[guxudaozhang;zhangsongxi;zhangsanfeng;zhangsan;liuxiran]],["text"]=[[武当派]],["titleImg"]=[[titleImg1.png]]},["8"]={["descri"]=[[镇岳宫倚壁而构，四边松林蔽日，景色幽美。宫前有玉井，相传井中曾生千叶白莲。这里地势略为平坦，上、下山的游客多在此稍作休息再继续前行。]],["family"]=[[huashan]],["showNpc"]=[[zhaotianlong;motianxiong;bailiyun;duanmuming;lixiazi;xuqianmo]],["text"]=[[华山]],["titleImg"]=[[titleImg1.png]]},["9"]={["descri"]=[[昆仑三圣堂乃“昆仑三圣”何足道所建，原为了修身养性，读书练功。随着昆仑派日益壮大，名声远播，这里便成了昆仑派聚众议事，接待各路江湖英雄的地方。]],["family"]=[[kunlun]],["showNpc"]=[[wenxiaoxiao;yujizi;yuzhenzi;hedonglai;heyunchong;hemingqing]],["text"]=[[昆仑派]],["titleImg"]=[[titleImg1.png]]}},["Sheet2"]={}}00000000000000